329	// --- rules ------------------------------------------------------------------
330	
331	func (h *handler) createRule(w http.ResponseWriter, r *http.Request) {
332		var request struct {
333			ID      string  `json:"id"`
334			Metric  string  `json:"metric"`
335			Trigger float64 `json:"trigger"`
336			Recover float64 `json:"recover"`
337		}
338		if err := decodeJSON(r, &request); err != nil {
339			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
340			return
341		}
342		ruleID := strings.TrimSpace(request.ID)
343		metric := strings.TrimSpace(request.Metric)
344		if ruleID == "" {
345			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
346			return
347		}
348		if metric == "" {
349			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric is required"})
350			return
351		}
352		if !finiteFloat(request.Trigger) || !finiteFloat(request.Recover) {
353			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "thresholds must be finite numbers"})
354			return
355		}
356		if request.Recover >= request.Trigger {
357			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
358			return
359		}
360		rule, err := h.store.CreateRule(r.PathValue("id"), ruleID, metric, request.Trigger, request.Recover)
361		if errors.Is(err, ErrDeviceNotFound) {
362			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
363			return
364		}
365		if errors.Is(err, ErrRuleConflict) {
366			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
367			return
368		}
369		if errors.Is(err, ErrStorageUnavailable) {
370			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
371			return
372		}
373		if err != nil {
374			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
375			return
376		}
377		writeJSON(w, http.StatusCreated, rule)
378	}
379	
380	func (h *handler) listRules(w http.ResponseWriter, r *http.Request) {
381		rules, err := h.store.ListRules(r.PathValue("id"))
382		if errors.Is(err, ErrDeviceNotFound) {
383			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
384			return
385		}
386		if err != nil {
387			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
388			return
389		}
390		writeJSON(w, http.StatusOK, map[string]any{"rules": rules})
391	}
392	
393	func (h *handler) getRule(w http.ResponseWriter, r *http.Request) {
394		rule, err := h.store.GetRule(r.PathValue("id"), r.PathValue("ruleId"))
395		if errors.Is(err, ErrDeviceNotFound) {
396			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
397			return
398		}
399		if errors.Is(err, ErrRuleNotFound) {
400			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
401			return
402		}
403		if err != nil {
404			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
405			return
406		}
407		writeJSON(w, http.StatusOK, rule)
408	}
409	
410	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
411		var request struct {
412			Metric  *string  `json:"metric"`
413			Trigger *float64 `json:"trigger"`
414			Recover *float64 `json:"recover"`
415			Enabled *bool    `json:"enabled"`
416			Version int64    `json:"version"`
417		}
418		if err := decodeJSON(r, &request); err != nil {
419			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
420			return
421		}
422		if request.Version < 1 {
423			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
424			return
425		}
426		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
427			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
428			return
429		}
430		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
431			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
432			return
433		}
434		if request.Recover != nil && !finiteFloat(*request.Recover) {
435			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
436			return
437		}
438		update := ruleUpdate{}
439		if request.Metric != nil {
440			metric := strings.TrimSpace(*request.Metric)
441			update.Metric = &metric
442		}
443		if request.Trigger != nil {
444			update.Trigger = request.Trigger
445		}
446		if request.Recover != nil {
447			update.Recover = request.Recover
448		}
449		if request.Enabled != nil {
450			update.Enabled = request.Enabled
451		}
452		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
453		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
454			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
455			return
456		}
457		if errors.Is(err, ErrVersionConflict) {
458			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
459			return
460		}
461		if errors.Is(err, ErrInvalidRule) {
462			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
463			return
464		}
465		if errors.Is(err, ErrStorageUnavailable) {
466			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
467			return
468		}
469		if err != nil {
470			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
471			return
472		}
473		writeJSON(w, http.StatusOK, rule)
474	}
