478	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
479		query := r.URL.Query()
480		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
481		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
482			if raw != alertStatusActive && raw != alertStatusEnded {
483				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
484				return
485			}
486			filter.Status = raw
487		}
488		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
489			switch raw {
490			case "true", "1":
491				v := true
492				filter.Acknowledged = &v
493			case "false", "0":
494				v := false
495				filter.Acknowledged = &v
496			default:
497				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
498				return
499			}
500		}
501		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
502		if errors.Is(err, ErrDeviceNotFound) {
503			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
504			return
