730	type alertEvaluator struct {
731		state        *deviceState
732		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
733		created      []*Alert
734		ended        []*Alert
735		nextID       int64
736	}
737	
738	func newAlertEvaluator(state *deviceState) *alertEvaluator {
739		eval := &alertEvaluator{
740			state:        state,
741			activeByRule: make(map[string]int64, len(state.rules)),
742			nextID:       int64(len(state.alerts)) + 1,
743		}
744		for id, rs := range state.rules {
745			eval.activeByRule[id] = rs.activeAlertID
746		}
747		return eval
748	}
749	
750	// evaluate judges one accepted sample. A value at or above the trigger opens
751	// an alert (or keeps the existing one); a value at or below the recovery
752	// threshold ends the active alert; anything in between or a missing metric
753	// leaves state unchanged.
754	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
755		for _, rs := range eval.state.rules {
756			if !rs.rule.Enabled {
757				continue
758			}
759			value, ok := values[rs.rule.Metric]
760			if !ok {
761				continue
762			}
763			activeID := eval.activeByRule[rs.rule.ID]
764			if value >= rs.rule.Trigger && activeID == 0 {
765				alert := &Alert{
766					ID:                eval.nextID,
767					RuleID:            rs.rule.ID,
768					RuleVersion:       rs.rule.Version,
769					Metric:            rs.rule.Metric,
770					Trigger:           rs.rule.Trigger,
771					Recover:           rs.rule.Recover,
772					Status:            alertStatusActive,
773					TriggerSequence:   seq,
774					TriggerValue:      value,
775					TriggerObservedAt: observedAt,
776				}
777				eval.nextID++
778				eval.created = append(eval.created, alert)
779				eval.activeByRule[rs.rule.ID] = alert.ID
780			} else if value <= rs.rule.Recover && activeID != 0 {
781				var source *Alert
782				if activeID <= int64(len(eval.state.alerts)) {
783					source = eval.state.alerts[activeID-1]
784				} else {
785					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
786				}
787				alert := cloneAlert(*source)
788				alert.Status = alertStatusEnded
789				alert.EndReason = endReasonRecovered
790				alert.RecoverSequence = &seq
791				alert.RecoverValue = &value
792				alert.RecoverObservedAt = &observedAt
793				eval.ended = append(eval.ended, &alert)
794				eval.activeByRule[rs.rule.ID] = 0
795			}
796		}
797	}
798	
